package io.floci.aws.services.kinesisvideo;

import com.fasterxml.jackson.databind.JsonNode;
import io.floci.aws.core.common.AwsException;
import io.floci.aws.core.common.RequestConstraintCheck;

import java.util.List;

/**
 * Checks the Kinesis Video Streams requests against the constraints generated by
 * {@code tools/aws/regen_kinesisvideo_shapes.py}. A member of the wrong JSON type answers
 * {@code SerializationException}, more tags than the model allows answer the modeled
 * {@code TagsPerResourceExceededLimitException}, and every other violation is an
 * {@code InvalidArgumentException} in the standard wording.
 */
final class KinesisVideoRequestShapes {

    private static final RequestConstraintCheck.Messages INVALID_ARGUMENT =
            RequestConstraintCheck.standardMessages("InvalidArgumentException");

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/kinesisvideo-request-shapes.json", "Kinesis Video Streams request shapes",
            new RequestConstraintCheck.Messages() {
                @Override
                public AwsException type(String path, String type) {
                    String member = path.substring(path.indexOf('.') + 1);
                    return new AwsException("SerializationException", member + " must be a " + type + ".", 400);
                }

                @Override
                public AwsException bounds(String path, String type, Long min, Long max, Number size) {
                    if ("map".equals(type) && path.endsWith(".Tags") && max != null && size.longValue() > max) {
                        return new AwsException("TagsPerResourceExceededLimitException",
                                "A stream can have at most " + max + " tags.", 400);
                    }
                    return INVALID_ARGUMENT.bounds(path, type, min, max, size);
                }

                @Override
                public AwsException pattern(String path, String pattern) {
                    return INVALID_ARGUMENT.pattern(path, pattern);
                }

                @Override
                public AwsException enumValue(String path, List<String> values) {
                    return INVALID_ARGUMENT.enumValue(path, values);
                }

                @Override
                public AwsException required(String path) {
                    return INVALID_ARGUMENT.required(path);
                }
            });

    private KinesisVideoRequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        CHECK.check(operation, request);
    }
}
